// Everything a close reviewer would tick off by hand, decided by rule. Materiality from Config.
const cfg = $('Config').first().json;
const mat = Number(cfg.materiality_aed);
const tb = $('Accounting: trial balance').first().json.rows;
const prior = $('Accounting: prior period').first().json.rows;
const chk = $('Accounting: close checks').first().json;
const num = v => Number(String(v || '0').replace(/,/g, ''));
const checks = [];
const dr = tb.reduce((s, r) => s + num(r.debit), 0), cr = tb.reduce((s, r) => s + num(r.credit), 0);
checks.push({ check: 'Trial balance balances', result: Math.abs(dr - cr) < 1 ? 'PASS' : 'FAIL', detail: `Dr ${dr.toFixed(0)} / Cr ${cr.toFixed(0)}` });
const bu = chk.bank_unreconciled || [];
const oldBank = bu.filter(x => num(x.days_open) > 5);
checks.push({ check: 'Bank reconciled', result: oldBank.length ? 'FAIL' : bu.length ? 'WARN' : 'PASS', detail: `${bu.length} open items, ${oldBank.length} older than 5 days` });
const up = chk.unposted_invoices || [];
const upTotal = up.reduce((s, x) => s + num(x.amount), 0);
checks.push({ check: 'Supplier invoices posted', result: upTotal > mat ? 'FAIL' : up.length ? 'WARN' : 'PASS', detail: `${up.length} unposted, AED ${upTotal.toFixed(0)}` });
checks.push({ check: 'Suspense cleared', result: num(chk.suspense_balance) === 0 ? 'PASS' : num(chk.suspense_balance) > mat ? 'FAIL' : 'WARN', detail: `AED ${num(chk.suspense_balance).toFixed(0)} in suspense` });
const vat = chk.vat_control || {};
checks.push({ check: 'VAT control agrees to return', result: vat.return_filed ? 'PASS' : 'WARN', detail: `Output ${num(vat.output_vat).toFixed(0)}, input ${num(vat.input_vat).toFixed(0)}, net ${(num(vat.output_vat) - num(vat.input_vat)).toFixed(0)}; return ${vat.return_filed ? 'filed' : 'not yet filed'}` });
checks.push({ check: 'Fixed asset register agrees to GL', result: num(chk.fixed_asset_register_total) === num(chk.gl_fixed_assets) ? 'PASS' : 'FAIL', detail: `Register ${num(chk.fixed_asset_register_total).toFixed(0)} vs GL ${num(chk.gl_fixed_assets).toFixed(0)}` });
const ar90 = chk.aged_receivables_over_90 || [];
const ar90Total = ar90.reduce((s, x) => s + num(x.amount), 0);
checks.push({ check: 'Receivables over 90 days reviewed', result: ar90Total > mat ? 'WARN' : 'PASS', detail: `${ar90.length} invoices, AED ${ar90Total.toFixed(0)} over 90 days` });
// P&L lines, this month vs prior, from the two trial balances (credits negative)
const bal = rows => { const m = {}; for (const r of rows) { const k = r.account.slice(0, 1); const v = num(r.debit) - num(r.credit); m[r.name] = (m[r.name] || 0) + v; } return m; };
const cur = bal(tb), prv = bal(prior);
const plNames = tb.filter(r => /^[4-8]/.test(r.account)).map(r => r.name).filter((v, i, a) => a.indexOf(v) === i);
const pl = plNames.map(n => { const c = -(cur[n] || 0), p = -(prv[n] || 0); const isRev = /revenue/i.test(n); const cc = isRev ? c : -c, pp = isRev ? p : -p; return { line: n, current: Math.round(cc), prior: Math.round(pp), change: Math.round(cc - pp), change_pct: pp ? Math.round(1000 * (cc - pp) / Math.abs(pp)) / 10 : null }; });
const revenue = pl.find(x => /revenue/i.test(x.line)) || { current: 0, prior: 0 };
const costs = pl.filter(x => !/revenue/i.test(x.line)).reduce((s, x) => s + x.current, 0);
const costsPrior = pl.filter(x => !/revenue/i.test(x.line)).reduce((s, x) => s + x.prior, 0);
const fails = checks.filter(c => c.result === 'FAIL').length, warns = checks.filter(c => c.result === 'WARN').length;
return [{ json: { period: cfg.period, checks, pl, fails, warns, revenue: revenue.current, revenue_prior: revenue.prior, costs, costs_prior: costsPrior,
  profit: revenue.current - costs, profit_prior: revenue.prior - costsPrior, status: fails ? 'BLOCKED' : warns ? 'READY WITH NOTES' : 'READY' } }];

const r = $('Run close checks').first().json;
const ai = $json.output || {};
const lines = Array.isArray(ai.commentary) ? ai.commentary : (typeof ai === 'string' ? ai.split('\n') : [
  `Revenue AED ${r.revenue.toLocaleString()} against AED ${r.revenue_prior.toLocaleString()} last month.`,
  `Operating costs AED ${r.costs.toLocaleString()} (prior AED ${r.costs_prior.toLocaleString()}).`,
  `Profit AED ${r.profit.toLocaleString()} (prior AED ${r.profit_prior.toLocaleString()}).`]);
const biggest = [...r.pl].filter(x => x.change_pct !== null).sort((a, b) => Math.abs(b.change) - Math.abs(a.change)).slice(0, 3)
  .map(x => `${x.line}: ${x.change >= 0 ? 'up' : 'down'} AED ${Math.abs(x.change).toLocaleString()} (${x.change_pct}%) on last month`);
return [{ json: { period: r.period, status: r.status, fails: r.fails, warns: r.warns, checks: r.checks, pl: r.pl,
  commentary: [...lines, 'Largest movements:', ...biggest, 'Every figure above is traceable to the trial balance export attached to this run.'] } }];
